import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div className="component-preview relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout">
      {children}
    </div>
  );
}

import { useAsyncDebouncer } from "@tanstack/react-pacer/async-debouncer";
import type { ComponentProps } from "react";
import { StatefulButton } from "@/registry/erbium/ui/stateful-button";

export function AsyncStatefulButton({
  children,
  successLabel,
  variant,
}: {
  children: string;
  successLabel: string;
  variant?: ComponentProps<typeof StatefulButton>["variant"];
}) {
  const request = useAsyncDebouncer(async () => {}, { wait: 1200 });

  return (
    <StatefulButton
      variant={variant}
      onClick={async () => {
        await request.maybeExecute();
      }}
      successLabel={successLabel}
    >
      {children}
    </StatefulButton>
  );
}

export default function StatefulButtonDemo() {
  return (
    <div className="flex flex-wrap items-center gap-3">
      <AsyncStatefulButton successLabel="Saved">Save</AsyncStatefulButton>
      <AsyncStatefulButton successLabel="Updated" variant="outline">
        Update
      </AsyncStatefulButton>
    </div>
  );
}

import { useAsyncDebouncer } from "@tanstack/react-pacer/async-debouncer";
import { useForm } from "@tanstack/react-form";
import { useRef, useState } from "react";
import { Field, FieldError, FieldLabel } from "@/registry/erbium/ui/field";
import { Input } from "@/registry/erbium/ui/input";
import { shake } from "@/registry/erbium/lib/shake";
import { StatefulButton } from "@/registry/erbium/ui/stateful-button";
import type { StatefulButtonState } from "@/registry/erbium/ui/stateful-button";

function SubmitStatefulButton({
  isSubmitting,
  isSubmitSuccessful,
  submissionAttempts,
}: {
  isSubmitting: boolean;
  isSubmitSuccessful: boolean;
  submissionAttempts: number;
}) {
  const [dismissedAttempt, setDismissedAttempt] = useState(0);
  let state: StatefulButtonState = "idle";
  if (isSubmitting) {
    state = "loading";
  } else if (isSubmitSuccessful && submissionAttempts !== dismissedAttempt) {
    state = "success";
  }

  return (
    <StatefulButton
      type="submit"
      state={state}
      onStateChange={(nextState) => {
        if (nextState === "idle") {
          setDismissedAttempt(submissionAttempts);
        }
      }}
      successLabel="Subscribed"
    >
      Subscribe
    </StatefulButton>
  );
}

export default function StatefulButtonForm() {
  const emailRef = useRef<HTMLInputElement>(null);
  const request = useAsyncDebouncer(async () => {}, { wait: 1200 });
  const form = useForm({
    defaultValues: { email: "" },
    onSubmit: async () => {
      await request.maybeExecute();
    },
    onSubmitInvalid: ({ formApi }) => {
      if (formApi.state.fieldMeta.email?.errors.length) {
        shake(emailRef.current);
      }
    },
  });

  return (
    <form
      noValidate
      className="w-80 space-y-4"
      onSubmit={(event) => {
        event.preventDefault();
        void form.handleSubmit();
      }}
    >
      <form.Field
        name="email"
        validators={{
          onBlur: ({ value }) => (value.includes("@") ? undefined : "Enter a valid email address."),
        }}
      >
        {(field) => (
          <Field
            name={field.name}
            invalid={!field.state.meta.isValid}
            touched={field.state.meta.isTouched}
            dirty={field.state.meta.isDirty}
          >
            <FieldLabel>Email</FieldLabel>
            <Input
              ref={emailRef}
              type="email"
              value={field.state.value}
              onFocus={() => field.setErrorMap({ ...field.state.meta.errorMap, onBlur: undefined })}
              onBlur={field.handleBlur}
              onChange={(event) => field.handleChange(event.target.value)}
            />
            <FieldError errors={field.state.meta.errors} />
          </Field>
        )}
      </form.Field>
      <form.Subscribe
        selector={(state) =>
          [state.isSubmitting, state.isSubmitSuccessful, state.submissionAttempts] as const
        }
      >
        {([isSubmitting, isSubmitSuccessful, submissionAttempts]) => (
          <SubmitStatefulButton
            isSubmitting={isSubmitting}
            isSubmitSuccessful={isSubmitSuccessful}
            submissionAttempts={submissionAttempts}
          />
        )}
      </form.Subscribe>
    </form>
  );
}

